// [id, nome, xml, corte no XML (s), ângulo do Time Slice]
export const NODE_TRANSITIONS = [
  ['node-iris-barra', 'Íris + barra vertical (Node Video)', 't1', 0.9, 0],
  ['node-barras-time-slice', 'Barras + Time Slice (Node Video)', 't2', 0.883, 90],
];
/** Camadas da transição posicionadas no corte, escaladas para o tamanho do projeto. */
export function nodeTransitionLayers(P, key, xmlCut, cut) {
  const { project: Q } = xmlToProject(XML[key], key);
  const s = Math.max(P.width / Q.width, P.height / Q.height), dt = cut - xmlCut;
  const isMedia = (l) => l.props?.aeMedia;
  const shift = (pr) => { for (const k of pr.keys || []) k.t = +(k.t + dt).toFixed(4); };
  const out = [];
  for (const l of Q.layers) {
    if (isMedia(l)) continue;
    l.inPoint = +(l.inPoint + dt).toFixed(4); l.outPoint = +(l.outPoint + dt).toFixed(4);
    for (const pr of Object.values(l.transform)) shift(pr);
    for (const fx of l.effects) for (const pr of Object.values(fx.params)) if (pr && typeof pr === 'object') shift(pr);
    const pos = l.transform.position, mp = (v) => [(v[0] - Q.width / 2) * s + P.width / 2, (v[1] - Q.height / 2) * s + P.height / 2];
    pos.value = mp(pos.value); for (const k of pos.keys || []) k.v = mp(k.v);
    const sc = l.transform.scale; sc.value = sc.value.map((v) => v * s); for (const k of sc.keys || []) k.v = k.v.map((v) => v * s);
    l.name = `Transição · ${l.name}`;
    out.push(l);
  }
  return out;
}
/** Time Slice do Node Video (15 fatias, intervalo 2 quadros) só durante a transição. */
export function nodeTimeSlice(t0, t1, angle) {
  return createEffectInstance('timeSlice', { slices: 15, direction: angle === 90 ? 2 : 1, delay: { keys: [{ t: 0, v: 0, ease: 'hold' }, { t: t0, v: 2, ease: 'hold' }, { t: t1, v: 0, ease: 'hold' }] } }, 0);
}
